import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

// Kernel: C = A @ B, where A is (M,K) row-major, B is (K,N) row-major, C is (M,N) row-major.
template <class TA, class TB, class TC,
          class StrideA, class StrideB, class StrideC>
__global__ static void
gemm_device(cute::Shape<int,int,int> shape_MNK,
            TA const* A, StrideA dA,
            TB const* B, StrideB dB,
            TC      * C, StrideC dC)
{
  using namespace cute;

  // Represent full tensors.
  // mA: shape (M,K) accessed directly (row-major, stride (K,1))
  // mB: shape (N,K) is a transposed *view* of physical B (K,N) row-major,
  //     achieved purely through strides (1,N) without moving data.
  Tensor mA = make_tensor(make_gmem_ptr(A), make_shape(get<0>(shape_MNK), get<2>(shape_MNK)), dA); // (M,K)
  Tensor mB = make_tensor(make_gmem_ptr(B), make_shape(get<1>(shape_MNK), get<2>(shape_MNK)), dB); // (N,K)
  Tensor mC = make_tensor(make_gmem_ptr(C), make_shape(get<0>(shape_MNK), get<1>(shape_MNK)), dC); // (M,N)

  // Tile
  auto cta_tiler = make_shape(Int<128>{}, Int<128>{}, Int<32>{});
  auto cta_coord = make_coord(blockIdx.x, blockIdx.y, _);
  Tensor gA = local_tile(mA, cta_tiler, cta_coord, Step<_1,X,_1>{});
  Tensor gB = local_tile(mB, cta_tiler, cta_coord, Step<X,_1,_1>{});
  Tensor gC = local_tile(mC, cta_tiler, cta_coord, Step<_1,_1,X>{});

  // Shared memory (padded row stride to avoid bank conflicts on column access)
  // Double-buffered (2-stage) to allow prefetching the next K-tile while
  // computing on the current tile, hiding global memory load latency.
  constexpr int kPad = 4;
  constexpr int kSmemAStride = 32 + kPad;
  constexpr int kSmemBStride = 32 + kPad;
  extern __shared__ unsigned char smem_raw[];
  TA* smemA0 = reinterpret_cast<TA*>(smem_raw);
  TA* smemA1 = smemA0 + 128 * kSmemAStride;
  TB* smemB0 = reinterpret_cast<TB*>(smemA1 + 128 * kSmemAStride);
  TB* smemB1 = smemB0 + 128 * kSmemBStride;
  auto sA_layout = make_layout(make_shape(Int<128>{}, Int<32>{}),
                                make_stride(Int<kSmemAStride>{}, Int<1>{}));
  auto sB_layout = make_layout(make_shape(Int<128>{}, Int<32>{}),
                                make_stride(Int<kSmemBStride>{}, Int<1>{}));
  Tensor sA0 = make_tensor(make_smem_ptr(smemA0), sA_layout);
  Tensor sB0 = make_tensor(make_smem_ptr(smemB0), sB_layout);
  Tensor sA1 = make_tensor(make_smem_ptr(smemA1), sA_layout);
  Tensor sB1 = make_tensor(make_smem_ptr(smemB1), sB_layout);
  // Thread layouts
  auto tA = make_layout(make_shape(Int<32>{}, Int<8>{}));
  auto tB = make_layout(make_shape(Int<32>{}, Int<8>{}));
  auto tC = make_layout(make_shape(Int<16>{}, Int<16>{}));
  Tensor tAgA = local_partition(gA, tA, threadIdx.x);
  Tensor tBgB = local_partition(gB, tB, threadIdx.x);
  Tensor tAsA0 = local_partition(sA0, tA, threadIdx.x);
  Tensor tBsB0 = local_partition(sB0, tB, threadIdx.x);
  Tensor tAsA1 = local_partition(sA1, tA, threadIdx.x);
  Tensor tBsB1 = local_partition(sB1, tB, threadIdx.x);
  Tensor tCsA0 = local_partition(sA0, tC, threadIdx.x, Step<_1,X>{});
  Tensor tCsB0 = local_partition(sB0, tC, threadIdx.x, Step<X,_1>{});
  Tensor tCsA1 = local_partition(sA1, tC, threadIdx.x, Step<_1,X>{});
  Tensor tCsB1 = local_partition(sB1, tC, threadIdx.x, Step<X,_1>{});
  Tensor tCgC = local_partition(gC, tC, threadIdx.x, Step<_1,_1>{});
  Tensor tCrC = make_tensor_like(tCgC);
  clear(tCrC);
  // Loop over K with software pipelining (2-stage double buffering)
  int K_TILE_MAX = size<2>(tAgA);
  // Prologue: load first tile into buffer 0
  copy(tAgA(_,_,0), tAsA0);
  copy(tBgB(_,_,0), tBsB0);
  __syncthreads();
  for (int k_tile = 0; k_tile < K_TILE_MAX; ++k_tile) {
    int cur = k_tile & 1;
    // Prefetch the next K-tile into the other buffer while we compute
    // on the current tile, overlapping global memory latency with FMA work.
    if (k_tile + 1 < K_TILE_MAX) {
      if (cur == 0) {
        copy(tAgA(_,_,k_tile+1), tAsA1);
        copy(tBgB(_,_,k_tile+1), tBsB1);
      } else {
        copy(tAgA(_,_,k_tile+1), tAsA0);
        copy(tBgB(_,_,k_tile+1), tBsB0);
      }
    }
    if (cur == 0) {
      gemm(tCsA0, tCsB0, tCrC);
    } else {
      gemm(tCsA1, tCsB1, tCrC);
    }
    __syncthreads();
  }

  // Epilogue
  axpby(1.0f, tCrC, 0.0f, tCgC);
}

// Host wrapper
torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim()==2 && B.dim()==2,  "A and B must be 2D");
  TORCH_CHECK(A.scalar_type()==at::kFloat && B.scalar_type()==at::kFloat,
              "Expect float32 tensors");

  // A:[M,K] row-major, B:[K,N] row-major -> C = A @ B
  int M = (int)A.size(0);
  int K = (int)A.size(1);
  int N = (int)B.size(1);
  TORCH_CHECK((int)B.size(0)==K, "B.size(0) must equal K");

  TORCH_CHECK(M % 128 == 0 && N % 128 == 0 && K % 32 == 0,
              "This simple CUTE kernel requires M,N divisible by 128 and K divisible by 32");

  auto A_c = A.contiguous();
  auto B_c = B.contiguous();
  auto C   = torch::empty({M, N}, A.options());

  auto ptrA = A_c.data_ptr<float>();
  auto ptrB = B_c.data_ptr<float>();
  auto ptrC = C.data_ptr<float>();

  // A is (M,K) row-major -> stride (K,1) : direct access, no transpose trick needed.
  auto dA = make_stride(K, Int<1>{});
  // B is (K,N) row-major physically; viewed as mB shape (N,K) via stride (1,N)
  // gives mB(n,k) = B(k,n) without moving data.
  auto dB = make_stride(Int<1>{}, N);
  // C is (M,N) row-major -> stride (N,1)
  auto dC = make_stride(N, Int<1>{});

  auto shape_MNK = make_shape(M, N, K);

  dim3 dimBlock(256);
  dim3 dimGrid((M+127)/128, (N+127)/128);

  constexpr int kPad_launch = 4;
  constexpr int kSmemAStride_launch = 32 + kPad_launch;
  constexpr int kSmemBStride_launch = 32 + kPad_launch;
  size_t smem_bytes = 2 * (size_t)128 * kSmemAStride_launch * sizeof(float)
                     + 2 * (size_t)128 * kSmemBStride_launch * sizeof(float);
  using KernelPtrT = void(*)(cute::Shape<int,int,int>,
                              float const*, decltype(dA),
                              float const*, decltype(dB),
                              float*, decltype(dC));
  KernelPtrT kernel_ptr = &gemm_device<float, float, float,
                                       decltype(dA), decltype(dB), decltype(dC)>;
  auto attr_err = cudaFuncSetAttribute(
      kernel_ptr,
      cudaFuncAttributeMaxDynamicSharedMemorySize,
      (int)smem_bytes);
  TORCH_CHECK(attr_err == cudaSuccess,
              "cudaFuncSetAttribute failed: ", cudaGetErrorString(attr_err));
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  gemm_device<<<dimGrid, dimBlock, smem_bytes, stream>>>(shape_MNK, ptrA, dA, ptrB, dB, ptrC, dC);

  return C;
}
"""

cute_matmul_ext = load_inline(
    name="cute_matmul_inline",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["cute_matmul"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs a single square matrix multiplication (C = A * B)
    using a custom CUTE GEMM kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = cute_matmul_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_matmul(A.contiguous(), B.contiguous())

